INSERT INTO `forge_exercises` (`slug`, `name`, `category`, `muscleGroup`, `difficulty`, `equipment`, `durationMinutes`, `description`, `benefits`, `formInstructions`, `commonMistakes`, `correctMediaUrl`, `wrongMediaUrl`) VALUES
('bodyweight-squat', 'Bodyweight Squat', 'Strength', 'Quads · Glutes', 'Beginner', 'None', '5', 'A steady squat pattern using your own bodyweight, with depth and pace adjusted to what feels comfortable.', 'Everyday leg strength · Hip control · Confidence standing and sitting', 'Stand with feet about shoulder-width apart. Send your hips back and bend your knees only as far as feels controlled. Keep your feet grounded, then stand tall without rushing.', 'Rushing the lowering phase · Heels lifting · Forcing depth or a range that feels uncomfortable', NULL, NULL),
('wall-push-up', 'Wall Push-Up', 'Strength', 'Chest · Shoulders · Arms', 'Beginner', 'None', '4', 'A gentle push-up starting point using a clear wall for hand support. Step closer to make the angle easier.', 'Confidence with pushing · Adjustable effort · A simple equipment-free starting place', 'Face a clear wall and place both hands around chest height. Keep your body comfortably long, bend your elbows a small amount to bring your chest closer, and press away. Stand closer to the wall whenever you like.', 'Hands at an uncomfortable height · Holding your breath · Leaning farther than you can control', '/manus-storage/forge-bodyweight-wall_13c145dc.jpg', NULL),
('incline-push-up', 'Incline Push-Up', 'Strength', 'Chest · Shoulders · Arms', 'Beginner', 'None', '4', 'A bodyweight push-up variation using a clear wall as a raised surface. Adjust hand height and foot distance to find a comfortable angle.', 'Upper-body pushing strength · Trunk control · A gradual step between wall and floor variations', 'Place your hands on a clear wall at a comfortable height, slightly lower than a basic wall push-up if that feels steady. Step back until your body forms a manageable angle, bend your elbows, then press away. No furniture is needed.', 'Choosing a position that strains the shoulders or wrists · Hips drifting back · Moving faster than you can control', '/manus-storage/forge-bodyweight-wall_13c145dc.jpg', NULL),
('reverse-lunge', 'Reverse Lunge', 'Strength', 'Quads · Glutes', 'Beginner', 'None', '5', 'A step-back lunge for one-leg strength and balance. Keep the step short or use a wall lightly for confidence.', 'Single-leg strength · Balance · Hip and knee coordination', 'Stand beside a wall if you would like light support. Step one foot back, bend both knees only within a comfortable range, then press through the front foot to return. Switch sides.', 'Making the stance too narrow · Rushing the step · Forcing depth or balance', NULL, NULL),
('glute-bridge', 'Glute Bridge', 'Strength', 'Glutes · Hamstrings', 'Beginner', 'None', '4', 'A floor-based hip extension exercise that uses only your bodyweight and a comfortable range.', 'Hip extension · Glute activation · Accessible lower-body training', 'Lie on your back with knees bent and feet on the floor. Gently brace your middle, press through your feet, lift your hips to a comfortable height, pause, then lower with control.', 'Overarching the lower back · Pushing only through the toes · Rushing the lowering phase', NULL, NULL),
('dead-bug', 'Dead Bug', 'Core', 'Core', 'Beginner', 'None', '4', 'A floor-based core movement that coordinates opposite arm and leg actions with steady breathing.', 'Trunk control · Coordination · Breath-led movement', 'Lie on your back with knees bent. Exhale gently and lower one heel and the opposite arm only as far as you can stay in control. Return and switch sides.', 'Holding your breath · Moving too far too soon · Letting the back arch sharply', NULL, NULL),
('forearm-plank', 'Forearm Plank', 'Core', 'Core · Shoulders', 'Beginner', 'None', '3', 'A short, steady trunk-strength hold with the option to keep knees down and shorten the time.', 'Trunk endurance · Shoulder stability · Full-body coordination', 'Set your forearms down and make a comfortable line from head through hips. Knees can stay on the floor. Breathe normally and finish before your position changes.', 'Holding your breath · Letting the hips sag · Staying in the hold after form slips', NULL, NULL),
('forward-lunge', 'Forward Lunge', 'Strength', 'Quads · Glutes', 'Intermediate', 'None', '5', 'A step-forward lunge that builds single-leg coordination; a smaller step is a useful first variation.', 'Leg strength · Balance · Controlled direction changes', 'Stand tall, take a comfortable step forward, soften both knees, and press through the front foot to return. Alternate sides at a steady pace.', 'Taking a step that is too long · Rushing the return · Allowing balance to dictate a depth that feels wrong', NULL, NULL),
('split-squat', 'Split Squat', 'Strength', 'Quads · Glutes', 'Intermediate', 'None', '5', 'A stationary split-stance squat. Adjust stance length and range to suit your balance and comfort.', 'Single-leg strength · Hip control · Gradual range progression', 'Stand in a comfortable split stance. Keep your feet planted, lower a small distance, then press back up. Use a nearby wall for optional light balance support.', 'Feet on a tightrope · Dropping quickly · Forcing a deep range', NULL, NULL),
('calf-raise', 'Calf Raise', 'Strength', 'Calves · Ankles', 'Beginner', 'None', '3', 'A controlled rise onto the balls of the feet to practice lower-leg strength and ankle movement.', 'Calf strength · Ankle control · Everyday walking support', 'Stand with feet comfortably apart. Rise onto the balls of your feet, pause briefly, and lower with control. Lightly touch a wall if you want balance support.', 'Bouncing · Rolling the ankles outward · Rushing the lowering phase', NULL, NULL),
('wall-sit', 'Wall Sit', 'Strength', 'Quads · Glutes', 'Beginner', 'None', '3', 'A time-based leg-strength hold against a wall, with height and duration both adjustable.', 'Leg endurance · Pacing · Comfortable isometric strength', 'Lean your back against a clear wall and walk your feet forward. Slide down only a little, hold while breathing, then stand before the position becomes uncomfortable.', 'Sitting lower than feels manageable · Holding your breath · Staying in the hold after discomfort', NULL, NULL),
('knee-push-up', 'Knee Push-Up', 'Strength', 'Chest · Shoulders · Arms', 'Beginner', 'None', '4', 'A floor push-up with knees down that makes upper-body effort easy to scale.', 'Pushing strength · Trunk coordination · Adjustable progression', 'Start on your hands and knees with hands a little wider than your shoulders. Keep a long line from head to knees, lower your chest with control, and press away.', 'Hips folding toward heels · Elbows flaring sharply · Lowering beyond a comfortable range', NULL, NULL),
('push-up', 'Push-Up', 'Strength', 'Chest · Shoulders · Arms', 'Intermediate', 'None', '4', 'A full-bodyweight push-up option. Use fewer repetitions or return to a wall or knee variation whenever useful.', 'Upper-body strength · Trunk tension · Whole-body coordination', 'Start in a high plank with hands under or slightly wider than shoulders. Keep your body long, lower within a comfortable range, then press the floor away.', 'Hips sagging · Elbows flaring straight out · Forcing repetitions after control changes', NULL, NULL),
('slow-push-up', 'Slow-Lowering Push-Up', 'Strength', 'Chest · Shoulders · Arms', 'Advanced', 'None', '5', 'An advanced push-up variation progressed through a slower lowering phase—not added load.', 'Tempo control · Upper-body strength · Focused technique', 'Use the push-up variation you can perform with control. Lower over three comfortable counts, pause briefly if steady, then press away. Shorten the range or return to an easier variation at any time.', 'Choosing a variation that is too challenging · Losing trunk position · Forcing a slow descent beyond control', NULL, NULL),
('pike-push-up', 'Pike Push-Up', 'Strength', 'Shoulders · Arms · Core', 'Advanced', 'None', '4', 'A bodyweight shoulder-strength variation with a smaller range as an option.', 'Shoulder strength · Trunk control · Scalable bodyweight pressing', 'From hands and feet on the floor, lift your hips comfortably. Bend the elbows and lower your head a small distance between your hands, then press back up.', 'Forcing a deep range · Shifting all weight sharply into the hands · Holding your breath', NULL, NULL),
('plank-shoulder-tap', 'Plank Shoulder Tap', 'Core', 'Core · Shoulders', 'Intermediate', 'None', '4', 'A controlled shoulder-tap variation that challenges trunk stability; knees-down is a valid option.', 'Anti-rotation control · Shoulder stability · Slow coordination', 'From a high plank or knees-down position, gently tap one shoulder with the opposite hand. Keep hips as still as comfortable, then switch sides slowly.', 'Rocking the hips quickly · Rushing the taps · Using a position that strains the wrists', NULL, NULL),
('bird-dog', 'Bird Dog', 'Core', 'Core · Back · Glutes', 'Beginner', 'None', '4', 'A steady hands-and-knees movement that practices balance and trunk control without equipment.', 'Coordination · Trunk control · Comfortable back and hip movement', 'Start on hands and knees. Reach one arm and the opposite leg only as far as you can stay balanced. Return slowly and change sides; a smaller reach is fine.', 'Twisting the hips · Lifting the leg too high · Rushing the return', '/manus-storage/forge-bodyweight-floor_b538a0da.jpg', NULL),
('high-plank', 'High Plank', 'Core', 'Core · Shoulders', 'Intermediate', 'None', '3', 'A time-based trunk hold from the hands, with shorter holds or knees down as simple options.', 'Trunk endurance · Shoulder support · Breath and position awareness', 'Place hands under or slightly wider than shoulders, step feet back, and hold a steady position while breathing. Knees can stay down; stop before your shape changes.', 'Locking the breath · Letting the low back sag · Holding longer than you can control', NULL, NULL),
('side-plank', 'Side Plank', 'Core', 'Core · Hips · Shoulders', 'Intermediate', 'None', '3', 'A side-body hold that scales well by bending the lower knee or shortening the time.', 'Side-body endurance · Hip stability · Controlled balance', 'Lie on your side, support yourself on a forearm, and lift your hips a comfortable distance. Bend your bottom knee to make it easier and breathe steadily.', 'Forcing the hips high · Holding your breath · Continuing when shoulder or hip comfort changes', NULL, NULL),
('mountain-climber', 'Mountain Climber', 'Full Body', 'Core · Hips · Shoulders', 'Intermediate', 'None', '4', 'An adaptable alternating knee drive. Slow steps are a complete version; pace is optional.', 'Coordination · Trunk endurance · Adjustable whole-body effort', 'Start from hands and knees or a high plank. Bring one knee forward within a comfortable range, return it, and switch sides. Choose a pace that lets you breathe.', 'Moving too quickly · Hips bouncing · Continuing when wrists or shoulders feel uncomfortable', NULL, NULL),
('heel-taps', 'Heel Taps', 'Core', 'Core · Obliques', 'Beginner', 'None', '3', 'A gentle floor-based trunk exercise using small alternating reaches and a steady breath.', 'Trunk awareness · Side-body coordination · Controlled movement', 'Lie on your back with knees bent and feet on the floor. Lift your head only if comfortable, reach one hand toward the same-side heel, then switch sides.', 'Pulling the neck · Reaching beyond a comfortable range · Holding your breath', NULL, NULL),
('leg-lower', 'Bent-Knee Leg Lower', 'Core', 'Core · Hips', 'Intermediate', 'None', '4', 'A controlled single-leg lowering drill with bent knees and a small adjustable range.', 'Trunk control · Hip coordination · Gradual range practice', 'Lie on your back with knees bent. Gently brace and lower one foot toward the floor only as far as you can keep your back comfortable. Return and alternate.', 'Lowering both legs before ready · Arching the back sharply · Rushing the movement', NULL, NULL),
('squat-to-reach', 'Bodyweight Squat to Reach', 'Full Body', 'Legs · Hips · Shoulders', 'Beginner', 'None', '4', 'A simple bodyweight squat paired with an easy upward reach to connect strength and mobility.', 'Whole-body coordination · Comfortable shoulder range · Leg practice', 'Lower into a small, comfortable squat. As you stand, reach both arms upward only as far as feels easy. Keep the pace steady and the feet grounded.', 'Forcing the squat depth · Arching the back during the reach · Rushing between positions', NULL, NULL),
('reverse-lunge-knee-drive', 'Reverse Lunge to Knee Drive', 'Full Body', 'Legs · Hips · Core', 'Intermediate', 'None', '5', 'A balance-focused reverse lunge that finishes with a smooth knee lift; each part can be practiced separately.', 'Single-leg control · Balance · Hip coordination', 'Step one foot back into a comfortable lunge, return to standing, then lift that knee only as high as balance allows. Use a wall for optional light support, and switch sides.', 'Rushing the transition · Forcing the knee lift · Making the step too large', NULL, NULL),
('bear-crawl', 'Bear Crawl', 'Full Body', 'Core · Shoulders · Hips', 'Advanced', 'None', '3', 'A very short, controlled bear-crawl step for whole-body coordination. Holding the position or keeping knees down is a useful easier option.', 'Whole-body coordination · Trunk control · Short, adjustable effort', 'Start on hands and knees on a safe, clear floor. If comfortable, lift your knees just a little and take one small, controlled step; otherwise keep the knees down and practice the stable starting position.', 'Lifting the knees too high · Holding the breath · Continuing when wrist or knee comfort changes', NULL, NULL),
('burpee-step-back', 'Burpee', 'Full Body', 'Legs · Core · Shoulders', 'Advanced', 'None', '4', 'A low-impact, step-based whole-body option. Skip any part and slow the pace whenever useful.', 'Coordination · Whole-body effort · Self-selected intensity', 'From standing, bend your knees and place your hands on the floor. Step one foot back, then the other, step them forward again, and stand. A squat-to-reach is an easier alternative.', 'Jumping when stepping feels better · Rushing the transitions · Continuing through discomfort', NULL, NULL),
('cat-cow', 'Cat–Cow', 'Mobility', 'Spine · Shoulders · Hips', 'Beginner', 'None', '3', 'A gentle, breath-led change of spinal position on hands and knees. Keep the movement small and easy.', 'Spinal movement · Breath awareness · A calm reset between tasks', 'Begin on hands and knees. Slowly round your back as you breathe out, then return through neutral and gently lift the chest as you breathe in. Stay within a range that feels comfortable.', 'Forcing the back into end range · Moving quickly · Treating the breath as a count to keep up with', NULL, NULL),
('worlds-greatest-stretch', 'World’s Greatest Stretch', 'Mobility', 'Hips · Upper back', 'Beginner', 'None', '4', 'A quiet lunge-position mobility flow with an optional reach, paced by your breath.', 'Hip comfort · Upper-body rotation · Adaptable movement break', 'Take a comfortable step forward and soften both knees. Rest your hands wherever balance feels easy; gently turn your chest toward the front leg, then return and switch sides.', 'Taking a stance that feels unstable · Forcing rotation · Holding your breath', NULL, NULL),
('hip-90-90', 'Hip 90/90', 'Mobility', 'Hips', 'Beginner', 'None', '4', 'A seated side-to-side hip movement with plenty of options to keep the range small.', 'Hip movement options · Gentle coordination · A self-paced mobility break', 'Sit with knees bent and feet on the floor. Let both knees move slowly from side to side, using your hands for support if you want. A smaller range is always fine.', 'Forcing a knee toward the floor · Moving through pinching · Treating both sides as needing the same range', NULL, NULL),
('thoracic-rotation', 'Thoracic Rotation', 'Mobility', 'Upper back · Shoulders', 'Beginner', 'None', '4', 'A gentle side-lying rotation to explore comfortable upper-back movement.', 'Upper-back mobility · Shoulder coordination · Calm breathing', 'Lie on your side with knees bent and arms together. Slowly open your top arm across your body only as far as comfortable, then return and repeat.', 'Pulling the arm farther than comfortable · Letting the knees roll sharply · Rushing the breath', NULL, NULL),
('ankle-rock', 'Ankle Mobility', 'Mobility', 'Ankles · Calves', 'Beginner', 'None', '3', 'A small forward-and-back ankle movement that can be done standing or seated.', 'Ankle range awareness · Foot and lower-leg movement · Easy daily practice', 'Stand in a comfortable split stance or sit with feet on the floor. Gently move one knee forward over the foot, then back. Keep your whole foot relaxed and planted.', 'Forcing the heel to lift · Pushing into a sharp stretch · Comparing one side with the other', NULL, NULL),
('hip-flexor-rock', 'Hip Flexor Stretch', 'Mobility', 'Hips · Thighs', 'Beginner', 'None', '3', 'A gentle hip movement in a low lunge position with a small range and optional standing alternative.', 'Hip comfort · Comfortable range exploration · Breath-led mobility', 'Take a short split stance or kneel if comfortable. Keep your trunk tall and shift your hips forward a small amount, then return. Use a standing version if kneeling does not suit you.', 'Arching the back to create range · Forcing a stretch · Staying in a position that bothers the knee', NULL, NULL),
('glute-bridge-hold', 'Glute Bridge Hold', 'Strength', 'Glutes · Hamstrings', 'Beginner', 'None', '3', 'A time-based progression of the glute bridge, using only a comfortable lift and hold.', 'Hip extension endurance · Adjustable hold duration · Glute engagement', 'Set up as for a glute bridge. Lift to a comfortable height, breathe for a few seconds, then lower. Increase the hold gradually only if you stay comfortable.', 'Holding the breath · Lifting so high that the back arches · Adding hold time before control feels steady', NULL, NULL),
('single-leg-glute-bridge', 'Single-Leg Glute Bridge', 'Strength', 'Glutes · Hamstrings · Core', 'Advanced', 'None', '4', 'An advanced bridge variation. Return to a two-foot bridge or alternating heel lift whenever useful.', 'Single-leg hip strength · Balance · Trunk control', 'Begin with both feet on the floor. If comfortable, lift one foot a little and raise your hips a small distance without letting them twist. Alternate sides.', 'Dropping one side of the pelvis · Forcing height · Skipping the two-foot version that builds control', NULL, NULL),
('pause-squat', 'Pause Squat', 'Strength', 'Quads · Glutes · Core', 'Intermediate', 'None', '4', 'A bodyweight squat with a brief pause at a comfortable depth to build control without extra load.', 'Tempo control · Leg strength · Confidence in a chosen range', 'Lower into a comfortable bodyweight squat. Pause for one easy breath without relaxing into the joints, then stand smoothly. Make the pause shorter or omit it as needed.', 'Pausing lower than you can control · Holding your breath · Turning the pause into discomfort', NULL, NULL),
('step-back-squat', 'Step-Back Squat', 'Strength', 'Quads · Glutes', 'Beginner', 'None', '4', 'A small step-back squat that can be kept shallow and steady for comfortable leg practice.', 'Leg strength · Step coordination · Adjustable range', 'Stand with feet comfortably apart. Step one foot back a small distance, bend the knees only as far as feels controlled, then return and change sides. A wall may be used for light balance support.', 'Taking a long unstable step · Forcing depth · Rushing between sides', NULL, NULL),
('single-leg-squat', 'Supported Single-Leg Squat', 'Strength', 'Quads · Glutes · Hips', 'Advanced', 'None', '4', 'An advanced bodyweight squat variation with optional light wall support and a small range.', 'Single-leg strength · Balance · Progressive bodyweight control', 'Stand beside a wall for optional light fingertip support. Shift your weight over one foot and bend that knee a small, comfortable amount while the other foot floats. Return slowly and switch sides; a split squat is an easier alternative.', 'Forcing a deep range · Letting the knee collapse inward · Skipping the split-squat progression', NULL, NULL),
('squat-to-knee-drive', 'Squat to Knee Drive', 'Full Body', 'Legs · Hips · Core', 'Beginner', 'None', '4', 'A bodyweight squat followed by a comfortable standing knee lift. Make either part smaller whenever helpful.', 'Leg coordination · Balance practice · Adaptable whole-body movement', 'Do a small bodyweight squat, stand up steadily, then lift one knee to a comfortable height. Return to standing and change sides; the knee lift can be omitted.', 'Rushing the transition · Forcing the knee height · Choosing a squat depth that does not feel controlled', NULL, NULL),
('leg-raise', 'Bent-Knee Leg Raise', 'Core', 'Core · Hips', 'Intermediate', 'None', '4', 'A gradual leg-raise variation that starts with bent knees and a single leg at a time.', 'Trunk control · Hip coordination · A scalable core progression', 'Lie on your back with knees bent and feet down. Gently brace, lift one knee toward a comfortable height, and lower slowly. Only extend the leg farther if you can stay comfortable and in control.', 'Arching the back sharply · Raising both legs before ready · Holding your breath', NULL, NULL),
('standing-hip-hinge', 'Standing Hip Hinge', 'Strength', 'Hips · Hamstrings · Back', 'Beginner', 'None', '4', 'A bodyweight practice of sending the hips back and standing again, with no load or equipment.', 'Hip-hinge coordination · Back-of-leg awareness · Everyday lifting pattern', 'Stand tall, soften the knees, and move your hips back as your torso tips forward a little. Keep your back long and stand by bringing your hips forward again.', 'Turning the hinge into a deep squat · Rounding the back · Chasing a deeper stretch', NULL, NULL)
INSERT INTO `forge_programs` (`slug`, `name`, `description`, `difficulty`, `durationWeeks`, `equipment`, `sampleWorkouts`) VALUES
('foundation', 'Foundation', 'Build movement confidence with clear, repeatable bodyweight sessions and room to progress at your pace.', 'Beginner', '4', 'None required', '["Movement foundations · 20 min","Lower-body basics · 15 min","Mobility reset · 10 min"]'),
('strength', 'Strength', 'Progressive strength built with repetitions, tempo, range and bodyweight variations—never a gym membership or added load.', 'Beginner to intermediate', '6', 'None required', '["Full-body strength · 20 min","Push-up practice · 15 min","Lower-body progression · 25 min"]'),
('mobility', 'Mobility', 'A practical sequence for moving comfortably, exploring range and taking a breath between busy days.', 'All levels', '3', 'None required', '["Hips and ankles · 15 min","Spine in motion · 10 min","Full-body reset · 20 min"]'),
('life-stage', 'Life Stage', 'Flexible bodyweight training choices that respect changing schedules, energy and individual needs.', 'Adaptable', '4', 'None required', '["Choose your pace · 20 min","Strength, scaled · 15 min","Move and reset · 10 min"]')
